pub struct Solution;

impl Solution {
    pub fn letter_combinations(digits: String) -> Vec<String> {
        if digits.is_empty() {
            return Vec::new();
        }

        let map = |d: u8| -> &'static [u8] {
            match d {
                b'2' => b"abc",
                b'3' => b"def",
                b'4' => b"ghi",
                b'5' => b"jkl",
                b'6' => b"mno",
                b'7' => b"pqrs",
                b'8' => b"tuv",
                b'9' => b"wxyz",
                _ => b"",
            }
        };

        let digits_bytes = digits.as_bytes();
        let mut results = Vec::new();
        let mut current = Vec::with_capacity(digits_bytes.len());

        fn backtrack(
            digits: &[u8],
            index: usize,
            current: &mut Vec<u8>,
            results: &mut Vec<String>,
            map: &dyn Fn(u8) -> &'static [u8],
        ) {
            if index == digits.len() {
                if let Ok(s) = String::from_utf8(current.clone()) {
                    results.push(s);
                }
                return;
            }

            for &ch in map(digits[index]) {
                current.push(ch);
                backtrack(digits, index + 1, current, results, map);
                current.pop();
            }
        }

        backtrack(digits_bytes, 0, &mut current, &mut results, &map);
        results
    }
}

